baseline.sql:
WITH race_info AS (  
  SELECT raceId FROM races  
  WHERE name = 'Italian Grand Prix' AND year = 2017
), qualifying_q3 AS (
  SELECT driverId, number, q3 FROM qualifying 
  JOIN race_info ON qualifying.raceId = race_info.raceId
  WHERE q3 IS NOT NULL
), fastest_time AS (
  SELECT MIN(q3) as best_time FROM qualifying_q3
)
SELECT number FROM qualifying_q3
JOIN fastest_time ON qualifying_q3.q3 = fastest_time.best_time;

treatment.sql:
WITH race_info AS (
  SELECT raceId FROM races WHERE year = 1957 AND name = 'British Grand Prix'
),
participants AS (
  SELECT driverId FROM results WHERE raceId = (SELECT raceId FROM race_info)
),
classified_finishers AS (
  SELECT driverId FROM results WHERE raceId = (SELECT raceId FROM race_info) AND positionOrder IS NOT NULL
)
SELECT ROUND(CAST((SELECT COUNT(DISTINCT driverId) FROM classified_finishers) AS FLOAT) * 100.0 / (SELECT COUNT(DISTINCT driverId) FROM participants), 2) AS classified_finisher_percentage
;

WITH club_members_majors AS (
  SELECT DISTINCT link_to_major FROM member WHERE link_to_major IS NOT NULL
),
majors_with_no_members AS (
  SELECT m.major_id FROM major m
  LEFT JOIN club_members_majors c ON m.major_id = c.link_to_major
  WHERE c.link_to_major IS NULL
),
total_majors AS (
  SELECT COUNT(*) AS total FROM major
),
no_member_majors_count AS (
  SELECT COUNT(*) AS none FROM majors_with_no_members
)
SELECT ROUND((CAST(n.none AS FLOAT) / t.total) * 100, 2) AS percentage_of_majors_with_no_members
FROM total_majors t, no_member_majors_count n;

